// Position decorations beside the introduction instead of giving them their own row.
const artOrder={1:[0,3,1,2,0,3],2:[1,3,4],3:[2,5,2],4:[5,3],5:[4,0,5],6:[5]};
$$('.topic-panel').forEach((panel,topic)=>{if(!topic)return;let count=0;panel.querySelectorAll('.reading-card').forEach(card=>{if(card.matches('.distance-card,.interval-experiment,.performance-player,#scoreImport'))return;const heading=card.querySelector(':scope > h2');if(!heading)return;let art=card.querySelector(':scope > .section-art');if(!art){art=document.createElement('div');art.setAttribute('aria-hidden','true');card.prepend(art)}const choices=artOrder[topic]||[0,1,2,3,4,5],variant=choices[count++%choices.length];art.className='section-art card-decoration variant-'+variant;card.classList.add('illustrated-card');const lead=document.createElement('div');lead.className='card-art-lead';const firstParagraph=heading.nextElementSibling?.tagName==='P'?heading.nextElementSibling:null;heading.before(lead);lead.append(heading);if(firstParagraph)lead.append(firstParagraph)})});
